from wflib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 1600
b = Board('Wireframe_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it is for', ul('A wireframe shows what is on a screen and where, before any visual design. It answers: what does the person see, and what can they do?', 'It is the detailed twin of a screen flow: a flow shows how screens connect, a wireframe shows what is inside one.')),
 card('Grey with one colour', ul('Grey-blue for everything: lines <span class="mono">#CBD5E1</span>, fills <span class="mono">#F1F5F9</span>, text <span class="mono">#334155</span>.', '<b>Blue</b> marks the primary action and the selected choice. <b>Rose</b> marks a risky or failed thing. <b>Green</b> and <b>amber</b> appear only in status chips.', 'No brand colours, no photos, no decoration. The page is judged on structure.')),
 card('Blocks', ul('Made of the blocks on the Components page: navbar, sidebar, card, list item, form field, buttons, image placeholder, tab bar, bottom nav, search bar, table, chart, modal, sheet, toast, loading, empty and error.', 'Labels and buttons carry real words. Body text is grey bars. An image is a crossed box.', 'One primary button per screen. Secondary buttons are outlined.')),
 card('Devices and size', ul('Phone: frame 330 × 680 (screen 298 wide), 3 px ink border, 38 px corners. Tablet and desktop use the device frames from Components.', 'Desktop frame 1320 × 760 with a browser bar. Content margins 28 px, gap between cards 16 px.', 'Drawn at about 0.8 of real size for phones and 1 for desktop; labels stay readable.')),
 card('Annotations', ul('A numbered badge: dark circle 26 px, teal digits. Place it on the <b>corner</b> of what it explains, never over text.', 'The notes sit below the screens in three columns: a bold title, one line of text. Number in the same order as the screen, left to right and top to bottom.', 'A note says what the detail does or why, not what it looks like.')),
 card('Tap targets', ul('A red dot with a halo marks where a tap or click starts, for example the primary button.', 'One per transition at most. It sits on the target, off the label.', 'The same dot is used in screen flows, so the two diagram types agree.')),
 card('States', ul('Every screen that loads data is drawn four times: normal, loading, empty, error.', 'Loading: skeleton bars in the shape of the rows, then a spinner after about a second. Empty: dashed icon, one line, one action. Error: rose icon, plain words, retry first.')),
 card('Responsive', ul('Show the same content at three widths: desktop 1024 and up, tablet 640 to 1023, phone under 640.', 'Say what changes: columns, where the filters go, how the links fold. A short note per change.', 'Keep the three frames the same height so the difference is visible.')),
 card('With screen flows', ul('A screen in a flow at fidelity L3 is a wireframe from this page. It keeps the screen ID and the name (S12 · Cart).', 'Use the same blocks, so a screen can move between the two types without redrawing.')),
 card('Style and animation', ul('One style only: grey wireframe. An illustrated style would defeat the purpose.', 'Nothing animates. A wireframe is a still; motion belongs to a prototype.')),
 card('What a plugin can rely on', ul('A screen is: ID, name, device, state, a list of blocks (type, text, position in a grid) and a list of annotations (number, target, title, text).', 'A block is one of the types in Components. A position is a row, a column and a span, not free coordinates.', 'A responsive set is the same screen with three widths. A state set is the same screen with four states.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">Wireframe · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">The conventions for wireframes and what a plugin can rely on. The examples show an annotated phone flow, an annotated desktop screen, a responsive set and a state set.</div></div>{grid}</div>')
print(save6(b))
